layout(location = 0) in vec2 a_position;
smooth out vec3 v_color;
void main() {
    const vec3 colors[3] = vec3[3](vec3(1,0,0), vec3(0,1,0), vec3(0,0,1));
    v_color = colors[gl_VertexID];
    gl_Position = vec4(a_position, 0.0, 1.0);
}

