layout(location = 0) out vec4 out_color;
void main() { out_color = vec4(v_color, 1.0); }

#version 330 core
smooth in vec3 v_color;
layout(location = 0) out vec4 out_color;
void main() {
    ivec2 cell = ivec2(floor(gl_FragCoord.xy / 8.0));
    if ((cell.x + cell.y) % 2 == 0) discard;
    out_color = vec4(v_color, 1.0);
}
